const userStatus=document.getElementById("user-status");function renderUserStatus(){if(!userStatus)return;const t=localStorage.getItem("currentUser");if(!t)return userStatus.textContent="Hello, Guest",void(userStatus.href="auth.html");try{const e=JSON.parse(t),r=e.displayName||e.email.split("@")[0];userStatus.textContent=`Hello, ${r}`,userStatus.href="auth.html"}catch(t){userStatus.textContent="Hello, Guest",userStatus.href="auth.html"}}renderUserStatus(),window.addEventListener("storage",t=>{"currentUser"===t.key&&renderUserStatus()}),window.addEventListener("currentUserChanged",renderUserStatus);
